using bridge_util::Result;
struct Item {
  Commands::D3D9Command command = Commands::Bridge_Any;
  uint16_t reserved = 0;
  uint32_t sequence = 0;
  uint64_t published = 0;
  std::array<uint32_t, 12> payload{};
};
static_assert(sizeof(Item) == 64, "benchmark payload must match across architectures");
using Writer = bridge_util::AtomicCircularQueue<Item, bridge_util::Accessor::Writer>;
using Reader = bridge_util::AtomicCircularQueue<Item, bridge_util::Accessor::Reader>;
constexpr size_t kQueueBytes = 49152;
constexpr size_t kMapSize = 65536;
constexpr uint32_t kWarmupCount = 25000;
constexpr uint32_t kSampleInterval = 256;
struct ReaderStats {
  uint32_t validated = 0;
  uint32_t samples = 0;
  double p50Ns = 0;
  double p95Ns = 0;
  double p99Ns = 0;
  double maxNs = 0;
};
static_assert(sizeof(ReaderStats) == 40, "shared statistics layout changed");

void require(bool condition, const char* message) {
  if (!condition) { throw std::runtime_error(message); }
}
class Handle {
  HANDLE m_handle;
public:
  explicit Handle(HANDLE handle) : m_handle(handle) {
    require(m_handle != nullptr && m_handle != INVALID_HANDLE_VALUE, "handle creation failed");
  }
  ~Handle() { CloseHandle(m_handle); }
  HANDLE get() const { return m_handle; }
  Handle(const Handle&) = delete;
  Handle& operator=(const Handle&) = delete;
};
struct Memory {
  Handle handle;
  void* data;
  Memory(const std::string& name, bool create)
    : handle(create ? CreateFileMappingA(INVALID_HANDLE_VALUE, nullptr, PAGE_READWRITE,
        0, static_cast<DWORD>(kMapSize), name.c_str()) :
        OpenFileMappingA(FILE_MAP_ALL_ACCESS, FALSE, name.c_str()))
    , data(MapViewOfFile(handle.get(), FILE_MAP_ALL_ACCESS, 0, 0, kMapSize)) {
    require(data != nullptr, "mapping view failed");
  }
  ~Memory() { UnmapViewOfFile(data); }
  Memory(const Memory&) = delete;
  ReaderStats* stats() const {
    return reinterpret_cast<ReaderStats*>(static_cast<char*>(data) + kQueueBytes);
  }
};
uint64_t ticks() {
  LARGE_INTEGER value{};
  require(QueryPerformanceCounter(&value) != FALSE, "performance counter failed");
  return static_cast<uint64_t>(value.QuadPart);
}
double nanosecondsPerTick() {
  LARGE_INTEGER frequency{};
  require(QueryPerformanceFrequency(&frequency) != FALSE, "performance frequency failed");
  return 1.0e9 / static_cast<double>(frequency.QuadPart);
}
uint64_t fileTime(const FILETIME& value) {
  return (static_cast<uint64_t>(value.dwHighDateTime) << 32) | value.dwLowDateTime;
}
uint64_t processCpu(HANDLE process) {
  FILETIME creation{}, exit{}, kernel{}, user{};
  require(GetProcessTimes(process, &creation, &exit, &kernel, &user) != FALSE,
    "process CPU query failed");
  return fileTime(kernel) + fileTime(user);
}
Item makeItem(uint32_t sequence, bool measured) {
  Item item{};
  item.sequence = sequence;
  for (size_t index = 0; index < item.payload.size(); ++index) {
    item.payload[index] = (sequence * 0x9e3779b9u) ^
      (static_cast<uint32_t>(index) * 0x85ebca6bu);
  }
  if (measured && sequence % kSampleInterval == 0) { item.published = ticks(); }
  return item;
}
void requireItem(const Item& item, uint32_t sequence) {
  const auto expected = makeItem(sequence, false);
  require(item.command == expected.command && item.sequence == sequence &&
    item.reserved == 0 && item.payload == expected.payload,
    "benchmark payload was torn, stale, or out of order");
}
std::string narrowName(const std::wstring& wide) {
  std::string name;
  for (const wchar_t character : wide) {
    require(static_cast<uint32_t>(character) < 128, "expected ASCII mapping name");
    name.push_back(static_cast<char>(character));
  }
  return name;
}
Handle eventFor(const std::string& name, const char* suffix) {
  return Handle(CreateEventA(nullptr, FALSE, FALSE, (name + suffix).c_str()));
}
void consume(Reader& reader, uint32_t sequence, std::vector<uint64_t>* samples) {
  Result result = Result::Failure;
  const Item peeked = reader.peek(result, 30000);
  require(result == Result::Success, "benchmark peek stalled");
  if (samples && peeked.published) { samples->push_back(ticks() - peeked.published); }
  requireItem(peeked, sequence);
  const Item pulled = reader.pull(result, 30000);
  require(result == Result::Success && pulled.published == peeked.published,
    "benchmark pull disagreed with peek");
  requireItem(pulled, sequence);
}
void runReader(const std::string& name, uint32_t count, size_t capacity) {
  Memory memory(name, false);
  Reader reader(name, memory.data, kQueueBytes, capacity);
  auto ready = eventFor(name, "Ready");
  auto start = eventFor(name, "Start");
  auto done = eventFor(name, "Done");
  std::vector<uint64_t> samples;
  samples.reserve((static_cast<size_t>(count) + kSampleInterval - 1) / kSampleInterval);
  for (uint32_t index = 0; index < kWarmupCount; ++index) { consume(reader, index, nullptr); }
  require(SetEvent(ready.get()) != FALSE, "ready signal failed");
  require(WaitForSingleObject(start.get(), 30000) == WAIT_OBJECT_0, "benchmark start stalled");
  for (uint32_t index = 0; index < count; ++index) { consume(reader, index, &samples); }
  require(reader.isEmpty() && !samples.empty(), "benchmark queue was not drained");
  std::sort(samples.begin(), samples.end());
  const double scale = nanosecondsPerTick();
  auto quantile = [&](size_t percent) {
    return static_cast<double>(samples[(samples.size() - 1) * percent / 100]) * scale;
  };
  auto& stats = *memory.stats();
  stats.validated = count;
  stats.samples = static_cast<uint32_t>(samples.size());
  stats.p50Ns = quantile(50);
  stats.p95Ns = quantile(95);
  stats.p99Ns = quantile(99);
  stats.maxNs = static_cast<double>(samples.back()) * scale;
  require(SetEvent(done.get()) != FALSE, "completion signal failed");
}
void runBenchmark(const std::wstring& peer, uint32_t count, size_t capacity) {
  const auto name = "Local\\L4D2QueueBenchmark-" + std::to_string(GetCurrentProcessId()) +
    "-" + std::to_string(GetTickCount64());
  Memory memory(name, true);
  new (memory.stats()) ReaderStats{};
  Writer writer(name, memory.data, kQueueBytes, capacity);
  auto ready = eventFor(name, "Ready");
  auto start = eventFor(name, "Start");
  auto done = eventFor(name, "Done");
  std::wstring command = L"\"" + peer + L"\" --reader " +
    std::wstring(name.begin(), name.end()) + L" " + std::to_wstring(count) +
    L" " + std::to_wstring(capacity);
  STARTUPINFOW startup{};
  startup.cb = sizeof(startup);
  PROCESS_INFORMATION process{};
  require(CreateProcessW(peer.c_str(), command.data(), nullptr, nullptr, FALSE,
    0, nullptr, nullptr, &startup, &process) != FALSE, "benchmark peer launch failed");
  Handle child(process.hProcess);
  Handle childThread(process.hThread);
  try {
    for (uint32_t index = 0; index < kWarmupCount; ++index) {
      require(writer.push(makeItem(index, false)) == Result::Success, "warmup writer stalled");
    }
    require(WaitForSingleObject(ready.get(), 30000) == WAIT_OBJECT_0, "warmup reader stalled");
    const auto producerBefore = processCpu(GetCurrentProcess());
    const auto consumerBefore = processCpu(child.get());
    const auto begin = ticks();
    require(SetEvent(start.get()) != FALSE, "start signal failed");
    for (uint32_t index = 0; index < count; ++index) {
      require(writer.push(makeItem(index, true)) == Result::Success, "benchmark writer stalled");
    }
    const HANDLE completion[] = {done.get(), child.get()};
    require(WaitForMultipleObjects(2, completion, FALSE, 30000) == WAIT_OBJECT_0,
      "benchmark reader failed or stalled");
    const auto elapsed = ticks() - begin;
    const auto producerCpu = processCpu(GetCurrentProcess()) - producerBefore;
    const auto consumerCpu = processCpu(child.get()) - consumerBefore;
    require(WaitForSingleObject(child.get(), 30000) == WAIT_OBJECT_0, "benchmark peer exit stalled");
    DWORD exitCode = 1;
    require(GetExitCodeProcess(child.get(), &exitCode) != FALSE && exitCode == 0,
      "benchmark peer failed");
    const auto& stats = *memory.stats();
    require(stats.validated == count && elapsed > 0, "benchmark result incomplete");
    const double seconds = static_cast<double>(elapsed) * nanosecondsPerTick() / 1.0e9;
    const double totalCpuMs = static_cast<double>(producerCpu + consumerCpu) / 10000.0;
    std::printf("{\"messages\":%u,\"capacity\":%zu,\"producer_bits\":%zu,"
      "\"wall_ms\":%.6f,\"throughput_per_second\":%.6f,"
      "\"producer_cpu_ms\":%.6f,\"consumer_cpu_ms\":%.6f,\"total_cpu_ms\":%.6f,"
      "\"cpu_ns_per_message\":%.6f,\"latency_samples\":%u,"
      "\"latency_p50_ns\":%.6f,\"latency_p95_ns\":%.6f,\"latency_p99_ns\":%.6f,"
      "\"latency_max_ns\":%.6f}\n",
      count, capacity, sizeof(void*) * 8, seconds * 1000.0,
      static_cast<double>(count) / seconds, static_cast<double>(producerCpu) / 10000.0,
      static_cast<double>(consumerCpu) / 10000.0, totalCpuMs,
      totalCpuMs * 1.0e6 / static_cast<double>(count), stats.samples,
      stats.p50Ns, stats.p95Ns, stats.p99Ns, stats.maxNs);
  } catch (...) {
    TerminateProcess(child.get(), 1);
    WaitForSingleObject(child.get(), 5000);
    throw;
  }
}
int wmain(int argc, wchar_t** argv) {
  try {
    const bool reader = argc == 5 && std::wstring(argv[1]) == L"--reader";
    require(reader || argc == 4, "expected peer path, message count, and queue capacity");
    const auto count = static_cast<uint32_t>(std::stoul(argv[reader ? 3 : 2]));
    const auto capacity = static_cast<size_t>(std::stoul(argv[reader ? 4 : 3]));
    require(count >= kSampleInterval && capacity >= 2 && capacity <= 512,
      "invalid benchmark count or capacity");
    if (reader) { runReader(narrowName(argv[2]), count, capacity); }
    else { runBenchmark(argv[1], count, capacity); }
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "%s\n", error.what());
    return 1;
  }
}
